# A 16-cycle has vertices 0-1-2-...-15-0
# Adding a chord (u,v) creates two cycles of length |v-u| and 16-|v-u|
# For girth >= 8, we need both >= 8, so |v-u| must be exactly 8
# So chords connecting opposite vertices are safe

n = 16
base_edges = [(i, (i+1) % 16) for i in range(16)]
# Add all opposite chords
opposite_chords = [(i, (i+8) % 16) for i in range(8)]
edges_set = set(base_edges) | set(opposite_chords)
print(f"Total edges: {len(edges_set)}")
print(f"Edges: {sorted(edges_set)}")

def has_short_cycle(edges_set, max_len=7):
    adj = [[] for _ in range(n)]
    for u, v in edges_set:
        adj[u].append(v)
        adj[v].append(u)
    for start in range(n):
        parent = [-1] * n
        dist = [-1] * n
        stack = [(start, -1)]
        dist[start] = 0
        while stack:
            v, p = stack.pop()
            for w in adj[v]:
                if w == p:
                    continue
                if dist[w] == -1:
                    dist[w] = dist[v] + 1
                    parent[w] = v
                    stack.append((w, v))
                elif dist[w] + dist[v] + 1 <= max_len:
                    return True
    return False

def is_3_colorable(edges_set):
    adj = [[] for _ in range(n)]
    for u, v in edges_set:
        adj[u].append(v)
        adj[v].append(u)
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        used = set()
        for w in adj[v]:
            if colors[w] != -1:
                used.add(colors[w])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)

print(f"3-colorable: {is_3_colorable(edges_set)}")
print(f"Has short cycle: {has_short_cycle(edges_set)}")

